python3 -c "
from glom import glom, T, Spec, Literal, ROOT

# Test Literal as key - should now be evaluated
target = {'a': 1}
print('Testing Literal as key:')
try:
    result = glom(target, {Literal('b'): 'a'})
    print('Result:', result)
except Exception as e:
    print('Failed:', type(e).__name__, e)

# Test ROOT as key
target2 = {'key': 'value', 'other': 'data'}
print()
print('Testing ROOT as key:')
try:
    # ROOT['key'] evaluates to 'value' from target
    result = glom(target2, {ROOT['key']: 'other'})
    print('Result:', result)
except Exception as e:
    print('Failed:', type(e).__name__, e)

# Test nested evaluation with dynamic key
target3 = {'a': 'my_key', 'my_key': 'value'}
print()
print('Testing dynamic key from T:')
try:
    result = glom(target3, {T['a']: T[T['a']]})
    print('Result:', result)
except Exception as e:
    print('Failed:', type(e).__name__, e)
"
